function SelectField(props: FieldControlProps<'select'>) {
  const options = props.spec.options;
  if (props.spec.multiple) {
    const selected = Array.isArray(props.value) ? props.value : [];
    return (
      <CheckboxGroup
        id={props.id}
        className="ed-choices"
        value={selected}
        disabled={props.disabled}
        readOnly={props.readOnly}
        {...aria(props)}
        onValueChange={(next) =>
          props.onChange(
            options.map((o) => o.value).filter((v) => next.includes(v)),
          )
        }
      >
        {options.map((option) => (
          <label key={option.value} className="ed-choice">
            <Check value={option.value} />
            {option.label}
          </label>
        ))}
      </CheckboxGroup>
    );
  }
  return (
    <Choice
      id={props.id}
      name={props.name}
      value={typeof props.value === 'string' ? props.value : null}
      options={options}
      placeholder={props.spec.placeholder}
      required={props.required}
      disabled={props.disabled}
      readOnly={props.readOnly}
      {...aria(props)}
      onValueChange={(value) => props.onChange(value || undefined)}
    />
  );
}

/** One value from a list of labelled options. */
export function Choice({
  value,
  options,
  onValueChange,
  placeholder,
  name,
  required,
  disabled,
  readOnly,
  ...trigger
}: {
  value: string | null;
  options: readonly { value: string; label: string }[];
  onValueChange: (value: string) => void;
  placeholder?: string;
  name?: string;
  required?: boolean;
  disabled?: boolean;
  readOnly?: boolean;
  id?: string;
  'aria-label'?: string;
  'aria-describedby'?: string;
  'aria-invalid'?: true;
  'aria-required'?: true;
}) {
  return (
    <Select
      name={name}
      value={value}
      items={options.map((option) => ({ ...option }))}
      placeholder={placeholder ?? ''}
      required={required}
      disabled={disabled}
      readOnly={readOnly}
      onValueChange={(next) => {
        if (typeof next === 'string') onValueChange(next);
      }}
    >
      <SelectTrigger className="ed-input ed-select" {...trigger}>
        <SelectValue />
        <ChevronsUpDownIcon aria-hidden />
      </SelectTrigger>
      <SelectContent sideOffset={4} className="ed-popup ed-list">
        {options.map((option) => (
          <SelectItem
            key={option.value}
            value={option.value}
            className="ed-item"
          >
            {option.label}
            <SelectItemIndicator className="ed-item-end">
              <CheckIcon />
            </SelectItemIndicator>
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  );
}

const MARKS = [
  { mark: 'bold', label: 'Bold', text: 'B' },
  { mark: 'italic', label: 'Italic', text: 'I' },
  { mark: 'underline', label: 'Underline', text: 'U' },
  { mark: 'strike', label: 'Strikethrough', text: 'S' },
] as const;

const BLOCKS = [
  { node: 'heading', attrs: { level: 2 }, label: 'Heading', text: 'H2' },
  { node: 'bulletList', label: 'Bulleted list', text: '•' },
  { node: 'orderedList', label: 'Numbered list', text: '1.' },
] as const;

/** The formats a rich text field allows, as toolbar buttons. */
export function RichTextFormats({
  marks,
  blocks = true,
}: {
  marks?: readonly string[];
  blocks?: boolean;
}) {
  return (
    <>
      {MARKS.filter((m) => marks === undefined || marks.includes(m.mark)).map(
        (m) => (
          <Editor.RichTextToolbarButton
            key={m.mark}
            mark={m.mark}
            aria-label={m.label}
            title={m.label}
            className="ed-format"
            data-mark={m.mark}
          >
            {m.text}
          </Editor.RichTextToolbarButton>
        ),
      )}
      {blocks
        ? BLOCKS.map((b) => (
            <Editor.RichTextToolbarButton
              key={b.node}
              node={b.node}
              attrs={'attrs' in b ? b.attrs : undefined}
              aria-label={b.label}
              title={b.label}
              className="ed-format"
            >
              {b.text}
            </Editor.RichTextToolbarButton>
          ))
        : null}
    </>
  );
}

/**
 * Rich text with its formats; `suggest` completes text such as
 * `{{variables}}`. The editor comes from `Editor.Root richText`.
 */
export function RichTextField({
  suggest,
  ...props
}: FieldControlProps<'richText'> & {
  suggest?: React.ComponentProps<typeof Editor.RichTextField>['suggest'];
}) {
  return (
    <Editor.RichTextField suggest={suggest} className="ed-input ed-richtext">
      <Editor.RichTextToolbar className="ed-richtext-toolbar">
        <RichTextFormats marks={props.spec.marks} blocks={!props.spec.inline} />
      </Editor.RichTextToolbar>
    </Editor.RichTextField>
  );
}

function ListField(props: FieldControlProps<'list'>) {
  const items = props.value ?? [];
  const { min = 0, max = Number.POSITIVE_INFINITY } = props.spec;
  const label = nameOf(props);
  const locked = props.disabled || props.readOnly;
  const set = (next: unknown[]) => props.onChange(next);
  const move = (from: number, to: number) => {
    const next = [...items];
    const [moved] = next.splice(from, 1);
    next.splice(to, 0, moved);
    set(next);
  };
  return (
    <div
      id={props.id}
      role="group"
      aria-label={label}
      className="ed-list-field"
      {...aria(props)}
    >
      <ol>
        {items.map((item, index) => (
          <li key={index} className="ed-card">
            {props.renderElement?.({
              spec: { ...props.spec.of, label: `${label} ${index + 1}` },
              value: item,
              onChange: (next) => {
                const copy = [...items];
                copy[index] = next;
                set(copy);
              },
              id: `${props.id}-${index}`,
              name: `${props.name}[${index}]`,
              index,
              disabled: props.disabled,
              readOnly: props.readOnly,
              invalid: false,
              describedBy: undefined,
            })}
            <div className="ed-row">
              <Button
                className="ed-button"
                data-variant="ghost"
                data-size="icon-xs"
                aria-label={`Move ${label} ${index + 1} up`}
                disabled={locked || index === 0}
                onClick={() => move(index, index - 1)}
              >
                <ArrowUpIcon />
              </Button>
              <Button
                className="ed-button"
                data-variant="ghost"
                data-size="icon-xs"
                aria-label={`Move ${label} ${index + 1} down`}
                disabled={locked || index === items.length - 1}
                onClick={() => move(index, index + 1)}
              >
                <ArrowDownIcon />
              </Button>
              <Button
                className="ed-button"
                data-variant="ghost"
                data-size="icon-xs"
                aria-label={`Remove ${label} ${index + 1}`}
                disabled={locked || items.length <= min}
                onClick={() => set(items.filter((_, i) => i !== index))}
              >
                <XIcon />
              </Button>
            </div>
          </li>
        ))}
      </ol>
      <Button
        className="ed-button"
        data-variant="outline"
        disabled={locked || items.length >= max}
        onClick={() => set([...items, emptyListElement(props.spec.of)])}
      >
        <PlusIcon />
        Add {label}
      </Button>
    </div>
  );
}

function ObjectField(props: FieldControlProps<'object'>) {
  const value = props.value ?? {};
  return (
    <fieldset id={props.id} className="ed-card" {...aria(props)}>
      <legend className="ed-sr">{nameOf(props)}</legend>
      {Object.entries(props.spec.fields).map(([key, spec]) => (
        <div key={key} className="ed-field">
          <span className="ed-label">{spec.label ?? key}</span>
          {props.renderNested?.({
            spec: { ...spec, label: spec.label ?? key },
            fieldKey: key,
            value: value[key],
            onChange: (next) => {
              const copy: Record<string, unknown> = { ...value };
              if (next === undefined) delete copy[key];
              else copy[key] = next;
              props.onChange(copy);
            },
            id: `${props.id}-${key}`,
            name: `${props.name}.${key}`,
            disabled: props.disabled,
            readOnly: props.readOnly,
            invalid: false,
            describedBy: undefined,
          })}
        </div>
      ))}
    </fieldset>
  );
}

